            i = j + 1
        else:
            i += 1

    # Replace placeholders
    for p in paras:
        if p._element is None:
            continue
        text = p.text
        if not pattern.search(text):
            continue
        new_text = text
        for key in pattern.findall(text):
            if key in data:
                new_text = new_text.replace('{{' + key + '}}', str(data[key]))
        if new_text != text:
            set_paragraph_text(p, new_text)


