from docx import Document
import re

doc = Document('/root/offer_letter_filled.docx')
pattern = re.compile(r'\{\{.*?\}\}')
found = []

def scan_paragraphs(paragraphs):
    for p in paragraphs:
        if p.text and pattern.search(p.text):
            found.append(p.text)

def scan_container(container):
    scan_paragraphs(container.paragraphs)
    for table in container.tables:
        for row in table.rows:
            for cell in row.cells:
                scan_container(cell)

scan_container(doc)
for section in doc.sections:
    scan_container(section.header)
    scan_container(section.footer)

print('placeholders_found', len(found))
if found:
    for t in found:
        print(t)
